func newTrailCmd() *cobra.Command {
	var insecureHTTPAuth bool

	cmd := &cobra.Command{
		Use:    "trail",
		Short:  "Manage trails for your branches",
		Hidden: true,
		Args:   cobra.NoArgs,
		Long:   "A trail ties together the context for a branch. Use `entire trail` to view, create, update, or watch it.",
