package cli

import (
	"context"
	"fmt"
	"io"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/api"
	"github.com/entireio/cli/cmd/entire/cli/gitremote"
	"github.com/entireio/cli/cmd/entire/cli/settings"
)

const (
	// trailEnablementCacheTTL bounds how long hook-time model-context injection
	// trusts the clone-local trails cache before treating it as unknown. Trail
	// commands refresh opportunistically, and SessionStart refreshes stale/unknown
	// entries before TurnStart.
	trailEnablementCacheTTL = time.Hour

	// trailEnablementRefreshTimeout bounds best-effort refreshes from hooks and
	// trailing command refreshes. Trail command success updates the cache without
	// an extra probe; this timeout mostly protects error/session-start probes.
	trailEnablementRefreshTimeout = 3 * time.Second
)

type trailEnablementCacheStatus int

const (
	trailEnablementCacheUnknown trailEnablementCacheStatus = iota
	trailEnablementCacheEnabled
	trailEnablementCacheDisabled
)

type trailEnablementScope struct {
	Forge     string
	Owner     string
	Repo      string
	RepoKey   string
	APIBase   string
	Supported bool
}

// trailsEnabledForRepo reports the locally cached server-side trails
// enablement for this repo. It intentionally performs no auth or network I/O:
// this runs on the agent TurnStart path. It does validate the cache against the
// current origin remote and API base so an origin/API change fails closed.
func trailsEnabledForRepo(ctx context.Context) bool {
	return cachedTrailsEnablementForRepo(ctx, time.Now()) == trailEnablementCacheEnabled
}

func cachedTrailsEnablementForRepo(ctx context.Context, now time.Time) trailEnablementCacheStatus {
	prefs, err := settings.LoadClonePreferences(ctx)
	if err != nil || prefs.TrailsEnabled == nil || prefs.TrailsEnabledCheckedAt == nil {
		return trailEnablementCacheUnknown
	}

	scope, err := currentTrailEnablementScope(ctx)
	if err != nil || !trailEnablementCacheMatchesScope(prefs, scope) || trailEnablementCacheExpired(*prefs.TrailsEnabledCheckedAt, now) {
		return trailEnablementCacheUnknown
	}

	if *prefs.TrailsEnabled {
		return trailEnablementCacheEnabled
	}
	return trailEnablementCacheDisabled
}

func trailEnablementCacheMatchesScope(prefs *settings.ClonePreferences, scope trailEnablementScope) bool {
	return prefs.TrailsEnabledRepoKey == scope.RepoKey && prefs.TrailsEnabledAPIBase == scope.APIBase
}

func trailEnablementCacheExpired(checkedAt time.Time, now time.Time) bool {
	if checkedAt.IsZero() {
		return true
	}
	if now.Before(checkedAt) {
		return true
	}
	return now.Sub(checkedAt) > trailEnablementCacheTTL
}

func currentTrailEnablementScope(ctx context.Context) (trailEnablementScope, error) {
	rawURL, err := gitremote.GetRemoteURL(ctx, "origin")
	if err != nil || strings.TrimSpace(rawURL) == "" {
		return trailEnablementScope{}, fmt.Errorf("get origin remote: %w", err)
	}
	info, err := gitremote.ParseURL(rawURL)
	if err != nil {
		return trailEnablementScope{}, fmt.Errorf("parse origin remote: %w", err)
	}
	return trailEnablementScope{
		Forge:     info.Forge,
		Owner:     info.Owner,
		Repo:      info.Repo,
		RepoKey:   trailEnablementRepoKey(info.Forge, info.Owner, info.Repo),
		APIBase:   api.BaseURL(),
		Supported: info.Forge != "",
	}, nil
}

func trailEnablementRepoKey(forge, owner, repo string) string {
	return strings.Join([]string{forge, owner, repo}, "/")
}

// saveTrailsEnabledForRepo persists the server-side trails enablement cache in
// clone-local preferences (.git/entire/preferences.json). The value is not
// committed and is shared by linked worktrees of the same clone.
func saveTrailsEnabledForRepo(ctx context.Context, enabled bool) error {
	scope, err := currentTrailEnablementScope(ctx)
	if err != nil {
		return err
	}
	return saveTrailsEnabledForScope(ctx, scope, enabled, time.Now())
}

func saveTrailsEnabledForRemote(ctx context.Context, forge, owner, repo string, enabled bool) error {
	scope := trailEnablementScope{
		Forge:     forge,
		Owner:     owner,
		Repo:      repo,
		RepoKey:   trailEnablementRepoKey(forge, owner, repo),
		APIBase:   api.BaseURL(),
		Supported: forge != "",
	}
	return saveTrailsEnabledForScope(ctx, scope, enabled, time.Now())
}

func saveTrailsEnabledForScope(ctx context.Context, scope trailEnablementScope, enabled bool, checkedAt time.Time) error {
	prefs, err := settings.LoadClonePreferences(ctx)
	if err != nil {
		return fmt.Errorf("load clone preferences: %w", err)
	}
	enabledCopy := enabled
	checkedAtUTC := checkedAt.UTC()
	prefs.TrailsEnabled = &enabledCopy
	prefs.TrailsEnabledCheckedAt = &checkedAtUTC
	prefs.TrailsEnabledRepoKey = scope.RepoKey
	prefs.TrailsEnabledAPIBase = scope.APIBase
	if err := settings.SaveClonePreferences(ctx, prefs); err != nil {
		return fmt.Errorf("save clone preferences: %w", err)
	}
	return nil
}

func refreshTrailsEnabledCacheIfStale(ctx context.Context) error {
	if cachedTrailsEnablementForRepo(ctx, time.Now()) != trailEnablementCacheUnknown {
		return nil
	}
	client, err := NewAuthenticatedAPIClient(ctx, false)
	if err != nil {
		return err
	}
	_, err = refreshTrailsEnabledCache(ctx, client)
	return err
}

func refreshTrailsEnabledCache(ctx context.Context, client *api.Client) (bool, error) {
	scope, err := currentTrailEnablementScope(ctx)
	if err != nil {
		return false, err
	}
	if !scope.Supported {
		if err := saveTrailsEnabledForScope(ctx, scope, false, time.Now()); err != nil {
			return false, err
		}
		return false, nil
	}
	enabled, err := client.TrailsEnabled(ctx, scope.Forge, scope.Owner, scope.Repo)
	if err != nil {
		return false, err
	}
	if err := saveTrailsEnabledForScope(ctx, scope, enabled, time.Now()); err != nil {
		return false, err
	}
	return enabled, nil
}

func noteTrailCommandEnablement(ctx context.Context, client *api.Client, commandErr error) {
	if commandErr == nil {
		// A successful repo-scoped trail command is itself proof that trails are
		// enabled/accesssible; avoid an extra network probe.
		_ = saveTrailsEnabledForRepo(ctx, true)
		return
	}

	// When a trail command fails after authentication, probe best-effort. This
	// covers cases like "no trail found for this branch": the command returns an
	// error, but the repo's trails endpoint is still reachable and should refresh
	// the cache to true. Transport/auth/probe errors leave the existing cache
	// untouched.
	refreshCtx, cancel := context.WithTimeout(ctx, trailEnablementRefreshTimeout)
	defer cancel()
	_, _ = refreshTrailsEnabledCache(refreshCtx, client)
}

func runAuthenticatedTrailAPI(ctx context.Context, errW io.Writer, insecureHTTP bool, fn func(context.Context, *api.Client) error) error {
	return runAuthenticatedDataAPI(ctx, errW, insecureHTTP, func(ctx context.Context, client *api.Client) error {
		err := fn(ctx, client)
		noteTrailCommandEnablement(ctx, client, err)
		return err
	})
}

	if err := validation.ValidateSessionID(event.SessionID); err != nil {
		return fmt.Errorf("invalid %s event: %w", event.Type, err)
	}

	// Claim the session for this agent. First-writer-wins: subsequent agents
	// firing SessionStart for the same session ID are no-ops. Used by
	// InitializeSession (TurnStart) and the dispatcher skip in
	// DispatchLifecycleEvent for cross-agent disambiguation when Cursor IDE
	// forwards hooks to both .cursor/hooks.json and .claude/settings.json.
	if _, hintErr := strategy.StoreAgentTypeHint(ctx, event.SessionID, ag.Type()); hintErr != nil {
		logging.Warn(logCtx, "failed to store agent hint on session start",
			slog.String("error", hintErr.Error()))
	}

	// Best-effort: keep the local trails-enabled cache fresh before TurnStart
	// decides whether to inject the `entire trail` hint into the model. This is
	// off the direct prompt path and bounded so a slow API cannot stall the agent
	// indefinitely. Failures leave the cache unknown; TurnStart will not mark the
	// session decided in that case, so a later refresh can still inject.
	refreshCtx, refreshCancel := context.WithTimeout(ctx, trailEnablementRefreshTimeout)
	if refreshErr := refreshTrailsEnabledCacheIfStale(refreshCtx); refreshErr != nil {
		logging.Debug(logCtx, "trails enablement refresh skipped",
			slog.String("error", refreshErr.Error()))
	}
	refreshCancel()

	// Build informational message — warn early if repo has no commits yet,
	// since checkpoints require at least one commit to work.
	message := sessionStartMessage(ag.Name(), false)
	if repo, err := strategy.OpenRepository(ctx); err == nil {
		defer repo.Close()
		if strategy.IsEmptyRepository(repo) {
			message = sessionStartMessage(ag.Name(), true)
		}
	}

	// Check for concurrent sessions and append count if any
