	// separate marker file). The TurnStart path only reads locally cached
	// enablement (validated against the current origin/API and freshness); it
	// performs no auth/network work. Unknown/stale cache entries deliberately do
	// NOT mark the session decided, so a SessionStart or trail-command refresh can
	// still allow a later turn to inject.
	decision := trailEnablementCacheUnknown
	mutated := false
	mutErr := strategy.MutateSessionState(ctx, event.SessionID, func(state *strategy.SessionState) error {
		if state.ContextInjectionDecided {
			return strategy.ErrMutationSkip
		}
		// Review/investigate sessions are task-specific and don't need the branch
		// trail pointer; skip without marking decided so normal sessions keep the
		// usual first-turn behavior.
		if state.Kind != "" {
