+	// When a trail command fails after authentication, probe best-effort. This
+	// covers cases like "no trail found for this branch": the command returns an
+	// error, but the repo's trails endpoint is still reachable and should refresh
+	// the cache to true. Transport/auth/probe errors leave the existing cache
+	// untouched.
+	refreshTrailsEnabledCacheBestEffort(ctx, client)
+}
+
+func runAuthenticatedTrailAPI(ctx context.Context, errW io.Writer, insecureHTTP bool, fn func(context.Context, *api.Client) error) error {
+	return runAuthenticatedDataAPI(ctx, errW, insecureHTTP, func(ctx context.Context, client *api.Client) error {
+		err := fn(ctx, client)
+		noteTrailCommandEnablement(ctx, client, err)
+		return err
+	})
+}

