// numbering is stable across saves.
func (f *File) ContextsForIssuer(issuer string) []*Context {
	if f == nil {
		return nil
	}
	want := trimURL(issuer)
	var out []*Context
	for _, c := range f.Contexts {
		if trimURL(c.CoreURL) == want {
			out = append(out, c)
